using System;
using System.Collections.Generic;
using UnityEditor;
using UnityEngine;
public sealed class DungeonRegionsEditor:EditorWindow {
 DungeonMapSettings physicalMap;DungeonRegionSettings asset;int selected;Vector2 scroll;bool erase;int paintMode,selectedPlacement;bool marqueeDragging;Vector2Int marqueeStart,marqueeEnd;
 static string[] map {get{return DungeonPrototype.DefaultMapRows;}}
 [InitializeOnLoadMethod] static void Init(){EditorApplication.delayCall+=Ensure;}
 static void Ensure(){if(EditorApplication.isPlayingOrWillChangePlaymode||DungeonRegionSettings.Current!=null||EnemyZoneSettings.Current==null)return;var a=CreateInstance<DungeonRegionSettings>();var r=new DungeonRegion{id=EnemyZoneSettings.Current.zoneId,displayName="Zona 1",enemies=EnemyZoneSettings.Current};for(int y=0;y<map.Length;y++)for(int x=0;x<map[y].Length;x++)if(map[y][x]=='.')r.cells.Add(new Vector2Int(x,y));a.regions=new[]{r};AssetDatabase.CreateAsset(a,"Assets/Resources/Exploration/Zones/DungeonRegions.asset");AssetDatabase.SaveAssetIfDirty(a);}
 string NewZonePath(DungeonRegion r){const string root="Assets/Resources/Exploration/Zones";int number=Mathf.Max(1,Array.IndexOf(asset.regions,r)+1);var match=System.Text.RegularExpressions.Regex.Match(r.displayName??"",@"\d+");int parsed;if(match.Success&&int.TryParse(match.Value,out parsed))number=parsed;string folder=number.ToString("00")+"-Zona"+number;if(!AssetDatabase.IsValidFolder(root+"/"+folder))AssetDatabase.CreateFolder(root,folder);return AssetDatabase.GenerateUniqueAssetPath(root+"/"+folder+"/Enemigos.asset");}
 [MenuItem("Editor/Carpeta de zonas",false,2005)] static void Folder(){var folder=AssetDatabase.LoadAssetAtPath<UnityEngine.Object>("Assets/Resources/Exploration/Zones");Selection.activeObject=folder;EditorGUIUtility.PingObject(folder);}
 [MenuItem("Editor/Zonas y encuentros",false,2004)] public static void Open(){Ensure();GetWindow<DungeonRegionsEditor>("Zonas y encuentros").Show();}
 public static void ApplyRectangle(DungeonRegionSettings target,int zone,string[] rows,Vector2Int from,Vector2Int to,bool erase){if(zone<0||zone>=target.regions.Length)return;Undo.IncrementCurrentGroup();Undo.SetCurrentGroupName("Asignar zona por marco");Undo.RecordObject(target,"Asignar zona por marco");for(int y=Mathf.Max(0,Mathf.Min(from.y,to.y));y<=Mathf.Min(rows.Length-1,Mathf.Max(from.y,to.y));y++)for(int x=Mathf.Max(0,Mathf.Min(from.x,to.x));x<=Mathf.Min(rows[y].Length-1,Mathf.Max(from.x,to.x));x++){if(rows[y][x]!='.')continue;var cell=new Vector2Int(x,y);foreach(var region in target.regions)region.cells.RemoveAll(c=>c==cell);if(!erase)target.regions[zone].cells.Add(cell);}EditorUtility.SetDirty(target);}
 void OnGUI(){physicalMap=(DungeonMapSettings)EditorGUILayout.ObjectField("Plano físico",physicalMap!=null?physicalMap:DungeonMapSettings.Current,typeof(DungeonMapSettings),false);if(physicalMap==null||!physicalMap.Valid){EditorGUILayout.HelpBox("Selecciona un plano válido.",MessageType.Warning);return;}var rows=physicalMap.rows;asset=(DungeonRegionSettings)EditorGUILayout.ObjectField("Mapa de regiones",asset!=null?asset:DungeonRegionSettings.Current,typeof(DungeonRegionSettings),false);if(asset==null)return;scroll=EditorGUILayout.BeginScrollView(scroll);EditorGUILayout.HelpBox("Selecciona una zona y pinta sus casillas. Pintar reasigna la casilla, evitando solapamientos. Negro = pared; gris = sin zona. Los colores solo se ven en este editor. Guarda fuera de Play Mode.",MessageType.Info);
  if(GUILayout.Button("Crear zona")){Undo.RecordObject(asset,"Crear zona");var list=new List<DungeonRegion>(asset.regions);list.Add(new DungeonRegion{displayName="Zona "+(list.Count+1),editorColor=Color.HSVToRGB((list.Count*.23f)%1,.65f,.9f)});asset.regions=list.ToArray();selected=list.Count-1;EditorUtility.SetDirty(asset);}
  if(asset.regions.Length>0){var names=Array.ConvertAll(asset.regions,r=>r.displayName);selected=EditorGUILayout.Popup("Zona",Mathf.Clamp(selected,0,names.Length-1),names);var r=asset.regions[selected];var so=new SerializedObject(asset);so.Update();var entry=so.FindProperty("regions").GetArrayElementAtIndex(selected);using(new EditorGUI.DisabledScope(true))EditorGUILayout.PropertyField(entry.FindPropertyRelative("id"));foreach(string key in new[]{"displayName","editorColor","enemies","spawnsEnabled","safeArea"})EditorGUILayout.PropertyField(entry.FindPropertyRelative(key));so.ApplyModifiedProperties();erase=EditorGUILayout.Toggle("Borrar asignación",erase);paintMode=GUILayout.Toolbar(paintMode,new[]{"Pintar zonas","Colocar enemigo","Marco rectangular"});if(paintMode==1&&asset.placedEnemies.Length>0)selectedPlacement=EditorGUILayout.Popup("Enemigo a colocar",Mathf.Clamp(selectedPlacement,0,asset.placedEnemies.Length-1),Array.ConvertAll(asset.placedEnemies,e=>e.speciesId+" / "+e.category));var connected=new HashSet<string>();foreach(var cell in r.cells)foreach(var direction in new[]{Vector2Int.up,Vector2Int.down,Vector2Int.left,Vector2Int.right}){var other=asset.At(cell+direction);if(other!=null&&other!=r)connected.Add(other.displayName);}EditorGUILayout.LabelField("Conecta por casillas con",string.Join(", ",connected));
   float size=Mathf.Clamp((position.width-40)/rows[0].Length,8,32);Rect grid=GUILayoutUtility.GetRect(size*rows[0].Length,size*rows.Length);for(int y=0;y<rows.Length;y++)for(int x=0;x<rows[y].Length;x++){var cell=new Vector2Int(x,y);Rect rect=new Rect(grid.x+x*size,grid.y+(rows.Length-1-y)*size,size-1,size-1);var at=asset.At(cell);EditorGUI.DrawRect(rect,rows[y][x]=='#'?Color.black:at!=null?at.editorColor:Color.gray);bool manual=Array.Exists(asset.placedEnemies,e=>e!=null&&e.enabled&&e.cell==cell);GUI.Label(rect,manual?"E "+x+","+y:x+","+y,new GUIStyle(EditorStyles.miniLabel){normal={textColor=Color.white}});var ev=Event.current;if(!EditorApplication.isPlaying&&paintMode!=2&&rows[y][x]=='.'&&(ev.type==EventType.MouseDown||ev.type==EventType.MouseDrag)&&ev.button==0&&rect.Contains(ev.mousePosition)){Undo.RecordObject(asset,"Asignar casilla");if(paintMode==1&&asset.placedEnemies.Length>0)asset.placedEnemies[selectedPlacement].cell=cell;else if(paintMode==0){foreach(var region in asset.regions)region.cells.RemoveAll(c=>c==cell);if(!erase)r.cells.Add(cell);}EditorUtility.SetDirty(asset);ev.Use();Repaint();}}
   if(paintMode==2&&!EditorApplication.isPlaying){Rect area=new Rect(grid.x,grid.y,size*rows[0].Length,size*rows.Length);var ev=Event.current;Vector2Int at=new Vector2Int(Mathf.Clamp(Mathf.FloorToInt((ev.mousePosition.x-grid.x)/size),0,rows[0].Length-1),rows.Length-1-Mathf.Clamp(Mathf.FloorToInt((ev.mousePosition.y-grid.y)/size),0,rows.Length-1));
    if(ev.type==EventType.MouseDown&&ev.button==0&&area.Contains(ev.mousePosition)){marqueeStart=marqueeEnd=at;marqueeDragging=true;ev.Use();Repaint();}
    if(marqueeDragging&&ev.type==EventType.MouseDrag){marqueeEnd=at;ev.Use();Repaint();}
    if(marqueeDragging){int minX=Mathf.Min(marqueeStart.x,marqueeEnd.x),maxX=Mathf.Max(marqueeStart.x,marqueeEnd.x),minY=Mathf.Min(marqueeStart.y,marqueeEnd.y),maxY=Mathf.Max(marqueeStart.y,marqueeEnd.y);Rect box=new Rect(grid.x+minX*size,grid.y+(rows.Length-1-maxY)*size,(maxX-minX+1)*size,(maxY-minY+1)*size);EditorGUI.DrawRect(box,new Color(1,.8f,0,.3f));if(ev.type==EventType.MouseUp&&ev.button==0){ApplyRectangle(asset,selected,rows,marqueeStart,marqueeEnd,erase);marqueeDragging=false;ev.Use();Repaint();}}
   }
   if(r.enemies!=null){SpeciesZoneEditor.QuickAdd(r.enemies);var values=r.enemies.LevelValues();var probs=r.enemies.LevelProbabilities();EditorGUILayout.LabelField("Niveles / probabilidad");for(int i=0;i<Math.Min(30,values.Length);i++)EditorGUILayout.LabelField("LV. "+values[i],(probs[i]*100).ToString("F2")+"%");foreach(var species in r.enemies.species)EditorGUILayout.LabelField(species.speciesId,"Peso "+species.weight);if(GUILayout.Button("Editar configuración de enemigos"))Selection.activeObject=r.enemies;if(GUILayout.Button("Clonar configuración para esta zona")){var config=Instantiate(r.enemies);config.zoneId=r.id;string path=NewZonePath(r);AssetDatabase.CreateAsset(config,path);Undo.RecordObject(asset,"Asignar configuración propia");r.enemies=config;EditorUtility.SetDirty(asset);}}
   if(GUILayout.Button("Crear configuración vacía para esta zona")){var config=CreateInstance<EnemyZoneSettings>();config.zoneId=r.id;AssetDatabase.CreateAsset(config,NewZonePath(r));Undo.RecordObject(asset,"Configurar zona");r.enemies=config;EditorUtility.SetDirty(asset);}
   if(GUILayout.Button("Eliminar zona seleccionada")){Undo.RecordObject(asset,"Eliminar zona");var list=new List<DungeonRegion>(asset.regions);list.RemoveAt(selected);asset.regions=list.ToArray();selected=0;EditorUtility.SetDirty(asset);}
  }
  var data=new SerializedObject(asset);data.Update();EditorGUILayout.PropertyField(data.FindProperty("legacyPlacements"));EditorGUILayout.PropertyField(data.FindProperty("initialRandomPerZone"));EditorGUILayout.PropertyField(data.FindProperty("placedEnemies"),new GUIContent("Enemigos manuales / eventos"),true);data.ApplyModifiedProperties();
  if(GUILayout.Button("Añadir enemigo manual")){Undo.RecordObject(asset,"Colocar enemigo");var list=new List<PlacedEnemyDefinition>(asset.placedEnemies);list.Add(new PlacedEnemyDefinition());asset.placedEnemies=list.ToArray();EditorUtility.SetDirty(asset);}
  foreach(var error in asset.Validate(rows))EditorGUILayout.HelpBox(error,MessageType.Warning);
  using(new EditorGUI.DisabledScope(EditorApplication.isPlaying))if(GUILayout.Button("Guardar zonas y encuentros")){var errors=asset.Validate(rows);if(errors.Count>0){EditorUtility.DisplayDialog("Zonas inválidas",string.Join("\n",errors.ToArray()),"Revisar");return;}AssetDatabase.SaveAssetIfDirty(asset);foreach(var r in asset.regions)if(r.enemies!=null)AssetDatabase.SaveAssetIfDirty(r.enemies);}
  EditorGUILayout.EndScrollView();
 }
}
[CustomPropertyDrawer(typeof(PlacedEnemyDefinition))] public class PlacedEnemyDrawer:PropertyDrawer {
 public override float GetPropertyHeight(SerializedProperty p,GUIContent l){return (p.isExpanded?14:1)*(EditorGUIUtility.singleLineHeight+3);}
 public override void OnGUI(Rect rect,SerializedProperty p,GUIContent label){float h=EditorGUIUtility.singleLineHeight+3;rect.height=EditorGUIUtility.singleLineHeight;p.isExpanded=EditorGUI.Foldout(rect,p.isExpanded,label,true);if(!p.isExpanded)return;EditorGUI.indentLevel++;foreach(string key in new[]{"id","enabled","cell","speciesId","randomLevel","fixedLevel","category","respawn","unique","countsTowardLimit","allowInSafeArea","trigger"}){rect.y+=h;var field=p.FindPropertyRelative(key);if(key=="speciesId"){var ids=new List<string>();var names=new List<string>();foreach(var enemy in EnemyCharacterCatalog.Current.enemies)if(enemy!=null){ids.Add(enemy.id);names.Add(enemy.character+(enemy.reservedForEvents?" (evento)":""));}int index=ids.IndexOf(field.stringValue);if(index<0){ids.Insert(0,field.stringValue);names.Insert(0,"ID: "+field.stringValue);index=0;}EditorGUI.BeginChangeCheck();int chosen=EditorGUI.Popup(rect,"Especie",index,names.ToArray());if(EditorGUI.EndChangeCheck())field.stringValue=ids[chosen];}else if(key=="id"){using(new EditorGUI.DisabledScope(true))EditorGUI.PropertyField(rect,field);}else EditorGUI.PropertyField(rect,field);}EditorGUI.indentLevel--;}
}
